CREATE OR REPLACE FUNCTION public.goal_confirmation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v numeric;valid boolean:=false;BEGIN IF TG_OP='UPDATE' AND NEW.student_id<>OLD.student_id THEN RAISE EXCEPTION 'Le propriétaire de la meta não pode ser alterado';END IF;IF NEW.status='alcancada' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN IF NOT public.is_trainer_of(NEW.student_id) THEN RAISE EXCEPTION 'Apenas o personal pode confirmar';END IF;IF NEW.metric='peso' THEN SELECT weight_kg INTO v FROM public.progress_records WHERE student_id=NEW.student_id ORDER BY measured_on DESC,created_at DESC LIMIT 1;valid:=NEW.initial_value IS NOT NULL AND NEW.target_value IS NOT NULL AND v IS NOT NULL AND NEW.initial_value<>NEW.target_value AND ((NEW.target_value>NEW.initial_value AND v>=NEW.target_value) OR (NEW.target_value<NEW.initial_value AND v<=NEW.target_value));ELSIF NEW.metric='treinos' THEN SELECT count(*) INTO v FROM public.training_sessions WHERE student_id=NEW.student_id AND finished_at IS NOT NULL AND performed_on>=NEW.created_at::date;valid:=NEW.target_value>0 AND v>=NEW.target_value;ELSE valid:=length(trim(coalesce(NEW.notes,'')))>0;END IF;IF NOT coalesce(valid,false) THEN RAISE EXCEPTION 'Registre evidências válidas antes de confirmar a conquista';END IF;NEW.completed_at:=now();NEW.confirmed_by:=auth.uid();PERFORM public.notify((SELECT user_id FROM public.students WHERE id=NEW.student_id),'Meta alcançada',NEW.name,'/aluno/evolucao',NULL);END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.public_team_contact() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('phone',contact_phone,'cta',public_cta,'invite_code',invite_code,'brand',business_name,'professional',professional_name,'photo',profile_photo_url,'logo',logo_url,'theme',blue_theme) FROM public.trainer_settings WHERE public.has_role(trainer_id,'admin') ORDER BY created_at LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.settings_media_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.profile_photo_url<>'' AND NEW.profile_photo_url !~ '^https://') OR (NEW.logo_url<>'' AND NEW.logo_url !~ '^https://') OR length(NEW.profile_photo_url)>2000 OR length(NEW.logo_url)>2000 OR length(NEW.contact_phone)>30 OR length(NEW.pix_key)>255 OR length(NEW.business_name)>150 OR length(NEW.professional_name)>150 THEN RAISE EXCEPTION 'Revise os links e os dados das configurações';END IF;RETURN NEW;END $$;
CREATE TRIGGER settings_media_validation BEFORE INSERT OR UPDATE ON public.trainer_settings FOR EACH ROW EXECUTE FUNCTION public.settings_media_guard();